import sys

def main():
    s = sys.stdin.read().strip()
    if not s:
        return

    present = [False] * 26
    for c in s:
        idx = ord(c) - ord('A')
        present[idx] = True

    best_len = 0
    best_diff = float('inf')
    best_start_idx = -1

    n = 26
    for start in range(n - 1, -1, -1):
        if not present[start]:
            continue
        for diff in range(1, n):
            current_len = 0
            curr = start
            while curr >= 0 and present[curr]:
                current_len += 1
                curr -= diff

            if current_len > best_len:
                best_len = current_len
                best_diff = diff
                best_start_idx = start
            elif current_len == best_len:
                if current_len == 1:
                    if start > best_start_idx:
                        best_diff = diff
                        best_start_idx = start
                else:
                    if diff < best_diff:
                        best_diff = diff
                        best_start_idx = start
                    elif diff == best_diff:
                        if start > best_start_idx:
                            best_start_idx = start

    result_chars = []
    curr = best_start_idx
    for _ in range(best_len):
        result_chars.append(chr(curr + ord('A')))
        curr -= best_diff

    print("".join(result_chars))

if __name__ == "__main__":
    main()
